const payload = $input.first().json;

const milestone = payload.milestone || 'report_completed';
const ticker = (payload.ticker || 'STOCK').toUpperCase();
const company_name = payload.company_name || ticker;
const phone_number = payload.phone_number || '+916382480091';

// Check CALLS_ENABLED safety flag from environment or payload override
const calls_enabled = (process.env.CALLS_ENABLED || 'false').toLowerCase() === 'true';

const allowed_milestones = payload.enabled_milestones || ['report_started', 'report_completed', 'critical_failure'];
const milestone_allowed = allowed_milestones.includes(milestone);

const should_call = calls_enabled && milestone_allowed;

let spoken_text = '';
if (milestone === 'report_started') {
  spoken_text = `Hello! This is F.R.I.D.A.Y., your AI financial analyst. I have initiated an institutional research audit on ${company_name} (${ticker}). Ingesting filings and concalls now.`;
} else if (milestone === 'report_completed') {
  spoken_text = `Hello! Your six-slide institutional research report on ${company_name} (${ticker}) is complete with high conviction. Would you like me to walk you through our valuation model or discuss the key risks?`;
} else if (milestone === 'critical_failure') {
  spoken_text = `F.R.I.D.A.Y. alert: The research run on ${ticker} encountered a missing filing gap and was halted to preserve verification integrity.`;
} else {
  spoken_text = `F.R.I.D.A.Y. milestone update for ${ticker}: ${milestone}.`;
}

return [{
  json: {
    milestone,
    ticker,
    company_name,
    phone_number,
    calls_enabled,
    milestone_allowed,
    should_call,
    spoken_text,
    call_id: `CALL_${Date.now()}`,
    timestamp: new Date().toISOString()
  }
}];

const data = $input.first().json;

// Safe dry-run response when CALLS_ENABLED is false
return [{
  json: {
    status: 'DRY_RUN_LOGGED',
    message: 'Outbound call suppressed by safety flag (CALLS_ENABLED=false). To enable cellular calls, set CALLS_ENABLED=true in .env.',
    call_details: data
  }
}];
